module kalman_filter(
    input clk,
    input rst,
    input [15:0] z,         // position measurement
    input [15:0] z_dot,     // velocity measurement
    input [15:0] R,         // measurement noise covariance
    output reg [15:0] x_k,  // estimated position
    output reg [15:0] v_k    // estimated velocity
);
    reg [15:0] P;           // estimation error covariance
    reg [15:0] K;           // Kalman gain
    parameter dt = 16'd1;  // time step

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            x_k <= 16'd0;
            v_k <= 16'd0;
            P <= 16'd1;
        end else begin
            // Prediction step
            x_k <= x_k + v_k * dt;
            v_k <= v_k;

            // Update step
            K <= P / (P + R);
            x_k <= x_k + K * (z - x_k);
            v_k <= v_k + K * (z_dot - v_k);
            P <= (16'd1 - K) * P;
        end
    end
endmodule

