module crc_generator(  
    input clk,  
    input reset,  
    input [15:0] data_in,  
    input [15:0] polynomial,  
    output reg [15:0] crc_out  
);  
    reg [15:0] crc;  
    integer i;  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            crc <= 16'b0;  
        end else begin  
            crc <= data_in;  
            for (i = 15; i >= 0; i = i - 1) begin  
                // Shift left and then XOR with polynomial if the MSB is 1  
                crc = crc << 1;  
                if (crc[15] == 1)  
                    crc = crc ^ polynomial;  
            end  
            crc_out <= crc;  
        end  
    end  
endmodule

