module timer_16bit(  
    input wire clk,  
    input wire rst,  
    input wire en,  
    input wire [15:0] max_value,  
    output reg [15:0] count  
);  
    always @(posedge clk or posedge rst) begin  
        if (rst)  
            count <= 16'b0;  
        else if (en) begin  
            if (count < max_value)  
                count <= count + 1;  
        end  
    end  
