module uart_tx #(parameter BAUD_RATE = 9600, parameter CLOCK_FREQ = 50000000) (  
    input wire clk,  
    input wire rst,  
    input wire [7:0] data_in,  
    input wire send,  
    output reg tx,  
    output reg busy  
);  
    localparam BIT_TIME = CLOCK_FREQ / BAUD_RATE;  
    reg [3:0] state;  
    reg [7:0] data;  
    reg [15:0] counter;  
    reg [3:0] bit_index;  

    localparam IDLE = 0, START_BIT = 1, DATA_BITS = 2, STOP_BIT = 3;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            tx <= 1;  
            busy <= 0;  
            state <= IDLE;  
            counter <= 0;  
            bit_index <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (send && !busy) begin  
                        busy <= 1;  
                        data <= data_in;  
                        state <= START_BIT;  
                        counter <= 0;  
                        tx <= 0; // Start bit  
                    end  
                end  
                START_BIT: begin  
                    if (counter < BIT_TIME - 1) begin  
                        counter <= counter + 1;  
                    end else begin  
                        counter <= 0;  
                        state <= DATA_BITS;  
                        bit_index <= 0;  
                        tx <= data[bit_index]; // Send first data bit  
                    end  
                end  
                DATA_BITS: begin  
                    if (counter < BIT_TIME - 1) begin  
                        counter <= counter + 1;  
                    end else begin  
                        counter <= 0;  
                        bit_index <= bit_index + 1;  
                        if (bit_index < 7)  
                            tx <= data[bit_index + 1]; // Send next data bit  
                        else begin  
                            state <= STOP_BIT;  
                            tx <= 1; // Send stop bit  
                        end  
                    end  
                end  
                STOP_BIT: begin  
                    if (counter < BIT_TIME - 1) begin  
                        counter <= counter + 1;  
                    end else begin  
                        busy <= 0;  
                        state <= IDLE;  
                        tx <= 1; // High state after stop bit  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

