module watchdog_timer(
    input wire clk,
    input wire rst_n,
    input wire heartbeat,
    input wire [3:0] timeout_value,
    output reg reset_signal
);
    reg [3:0] counter;
    reg timer_active;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 4'b0000;
            reset_signal <= 1'b0;
            timer_active <= 1'b0;
        end else begin
            if (heartbeat) begin
                counter <= 4'b0000; // reset the counter on heartbeat
                timer_active <= 1'b1;
            end else if (timer_active) begin
                if (counter < timeout_value) begin
                    counter <= counter + 1;
                end else begin
                    reset_signal <= 1'b1; // timeout occurred
                end
            end
        end
    end
endmodule

