module uart_tx #(parameter BAUD_RATE = 9600, parameter CLOCK_FREQ = 50000000)  
(  
    input wire clk,  
    input wire reset,  
    input wire start_tx,  
    input wire [7:0] data_in,  
    output reg tx,  
    output reg busy  
);  

    localparam IDLE = 2'b00, START = 2'b01, DATA = 2'b10, STOP = 2'b11;  
    reg [1:0] state = IDLE;  
    reg [3:0] bit_index = 0;  
    reg [15:0] baud_counter = 0;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            tx <= 1;  
            busy <= 0;  
            bit_index <= 0;  
            baud_counter <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (start_tx && !busy) begin  
                        busy <= 1;  
                        state <= START;  
                        tx <= 0; // start bit  
                    end  
                end  
                START: begin  
                    if (baud_counter == CLOCK_FREQ / BAUD_RATE - 1) begin  
                        baud_counter <= 0;  
                        state <= DATA;  
                        bit_index <= 0;  
                    end else begin  
                        baud_counter <= baud_counter + 1;  
                    end  
                end  
                DATA: begin  
                    if (baud_counter == CLOCK_FREQ / BAUD_RATE - 1) begin  
                        baud_counter <= 0;  
                        if (bit_index < 8) begin  
                            tx <= data_in[bit_index];  
                            bit_index <= bit_index + 1;  
                        end else begin  
                            state <= STOP;  
                        end  
                    end else begin  
                        baud_counter <= baud_counter + 1;  
                    end  
                end  
                STOP: begin  
                    if (baud_counter == CLOCK_FREQ / BAUD_RATE - 1) begin  
                        tx <= 1; // stop bit  
                        busy <= 0;  
                        state <= IDLE;  
                    end else begin  
                        baud_counter <= baud_counter + 1;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

