module cnn_layer (  
    input clk,  
    input reset,  
    input [15:0] input_feature_map, // 4x4 input feature map (16 bits)  
    input [8:0] kernel, // 3x3 kernel (9 bits)  
    output reg [7:0] output_feature_map // 2x2 output feature map (4 bits)  
);  
    reg [3:0] pixel[0:3][0:3]; // 4x4 input feature map storage  
    reg [2:0] k[0:2][0:2]; // 3x3 kernel storage  
    reg [7:0] conv_result;  
    integer i, j, m, n;  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            output_feature_map <= 0;  
        end else begin  
            // Load the input feature map and kernel  
            for (i = 0; i < 4; i = i + 1) begin  
                for (j = 0; j < 4; j = j + 1) begin  
                    pixel[i][j] <= input_feature_map[i*4 + j];  
                end  
            end  
            for (m = 0; m < 3; m = m + 1) begin  
                for (n = 0; n < 3; n = n + 1) begin  
                    k[m][n] <= kernel[m*3 + n];  
                end  
            end  
            // Perform convolution operation  
            for (i = 0; i < 2; i = i + 1) begin  
                for (j = 0; j < 2; j = j + 1) begin  
                    conv_result = 0;  
                    for (m = 0; m < 3; m = m + 1) begin  
                        for (n = 0; n < 3; n = n + 1) begin  
                            conv_result = conv_result + (pixel[i+m][j+n] * k[m][n]);  
                        end  
                    end  
                    // Apply ReLU activation  
                    output_feature_map[i*2 + j] <= (conv_result > 0) ? conv_result : 0;  
                end  
            end  
        end  
    end  
endmodule

