module binary_heap (
    input wire clk,
    input wire reset,
    input wire insert,
    input wire extract,
    input wire [7:0] data_in,
    output reg [7:0] min_out,
    output reg empty
);

    reg [7:0] heap [0:15];
    reg [3:0] size;

    initial begin
        size = 0;
        empty = 1;
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            size <= 0;
            empty <= 1;
        end else begin
            if (insert) begin
                if (size < 16) begin
                    heap[size] <= data_in;
                    size <= size + 1;
                    empty <= 0;
                    // Insert element and maintain heap property
                    // (simplified for brevity)
                end
            end
            if (extract) begin
                if (size > 0) begin
                    min_out <= heap[0];
                    heap[0] <= heap[size - 1];
                    size <= size - 1;
                    // Extract minimum and maintain heap property
                    // (simplified for brevity)
                end
            end
        end
    end
endmodule

