module deserializer (  
    input wire clk,  
    input wire reset,  
    input wire [3:0] parallel_in,  
    output reg [15:0] serial_out  
);  
    reg [3:0] data_buffer;  
    reg [3:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            serial_out <= 16'b0;  
            count <= 4'b0;  
            data_buffer <= 4'b0;  
        end else begin  
            if (count < 4) begin  
                data_buffer <= parallel_in;  
                serial_out <= {serial_out[11:0], data_buffer};  
                count <= count + 1;  
            end else begin  
                count <= 4'b0;  
            end  
        end  
    end  
endmodule

