module EEPROM (
    input wire clk,
    input wire write_enable,
    input wire read_enable,
    input wire reset,
    input wire [7:0] data_in,
    output reg [7:0] data_out
);

    reg [7:0] memory;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            memory <= 8'b0;
            data_out <= 8'b0;
        end else if (write_enable) begin
            memory <= data_in;
        end else if (read_enable) begin
            data_out <= memory;
        end
    end
endmodule

