module reset_controller(
    input wire clk,
    input wire reset,
    output reg out
);
    parameter DELAY = 10; // Delay duration in clock cycles
    reg [3:0] counter;
    reg reset_active;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            out <= 0; // Set output to reset state
            counter <= 0;
            reset_active <= 1;
        end else if (reset_active) begin
            if (counter < DELAY) begin
                counter <= counter + 1;
                out <= 0; // Remain in reset state
            end else begin
                out <= 1; // Normal state
                reset_active <= 0;
            end
        end
    end
endmodule

