module watchdog_timer (
    input wire clk,
    input wire reset_signal,
    output reg reset
);
    parameter TIMEOUT = 10;  // Timeout period
    reg [3:0] counter;

    always @(posedge clk or posedge reset_signal) begin
        if (reset_signal) begin
            counter <= 0;
            reset <= 0;
        end else begin
            if (counter < TIMEOUT) begin
                counter <= counter + 1;
                reset <= 0;
            end else begin
                reset <= 1;  // Activate reset after TIMEOUT
            end
        end
    end
endmodule

