module watchdog_timer #(parameter TIMEOUT = 10) (  
    input wire clk,  
    input wire kick,  
    output reg reset  
);  
    reg [3:0] counter;  

    always @(posedge clk) begin  
        if (kick) begin  
            counter <= 0;  
            reset <= 0;  
        end else if (counter < TIMEOUT) begin  
            counter <= counter + 1;  
            reset <= 0;  
        end else begin  
            reset <= 1;  
        end  
    end  
endmodule

