module viterbi_decoder (  
    input clk,  
    input rst,  
    input [3:0] input_bits,  
    output reg [3:0] decoded_bits,  
    output reg [7:0] path_metrics  
);  

    reg [1:0] state;  
    reg [3:0] next_decoded_bits;  
    reg [7:0] next_path_metrics;  

    // State encoding  
    parameter S0 = 2'b00,  
              S1 = 2'b01,  
              S2 = 2'b10,  
              S3 = 2'b11;  

    // Combinational logic for state transition and output  
    always @(*) begin  
        case (state)  
            S0: begin  
                next_decoded_bits = (input_bits[0] == 0) ? 4'b0000 : 4'b1111;  
                next_path_metrics = 8'h0F;  
            end  
            S1: begin  
                next_decoded_bits = (input_bits[1] == 0) ? 4'b0001 : 4'b1110;  
                next_path_metrics = 8'h1F;  
            end  
            S2: begin  
                next_decoded_bits = (input_bits[2] == 0) ? 4'b0010 : 4'b1101;  
                next_path_metrics = 8'h2F;  
            end  
            S3: begin  
                next_decoded_bits = (input_bits[3] == 0) ? 4'b0011 : 4'b1100;  
                next_path_metrics = 8'h3F;  
            end  
            default: begin  
                next_decoded_bits = 4'b0000;  
                next_path_metrics = 8'h00;  
            end  
        endcase  
    end  

    // Sequential logic for state update and output assignment  
    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= S0;  
            decoded_bits <= 4'b0000;  
            path_metrics <= 8'h00;  
        end else begin  
            state <= state + 1;  
            decoded_bits <= next_decoded_bits;  
            path_metrics <= next_path_metrics;  
        end  
    end  
endmodule

