module neural_network (  
    input wire clk,  
    input wire enable,  
    input wire [2:0] x,  
    output reg y  
);  
    reg [3:0] weights [0:2];  
    reg [3:0] bias;  
    reg [3:0] activation;  
    reg [3:0] output_error;  
    reg [3:0] target;  

    initial begin  
        weights[0] = 4'b0001;  
        weights[1] = 4'b0010;  
        weights[2] = 4'b0100;  
        bias = 4'b0001;  
        target = 4'b0001;  
    end  

    always @(posedge clk) begin  
        if (enable) begin  
            activation = (weights[0] * x[0]) + (weights[1] * x[1]) + (weights[2] * x[2]) + bias;  
            y = (activation > 4'b0100) ? 1'b1 : 1'b0;  

            // Backpropagation (simplified)  
            output_error = target - y;  
            weights[0] = weights[0] + (output_error * x[0]);  
            weights[1] = weights[1] + (output_error * x[1]);  
            weights[2] = weights[2] + (output_error * x[2]);  
            bias = bias + output_error;  
        end  
    end  
endmodule

