module sr_latch (  
    input wire S,  
    input wire R,  
    output reg Q  
);  
    always @ (S or R) begin  
        if (S && !R)  
            Q <= 1;  
        else if (!S && R)  
            Q <= 0;  
        // If both S and R are low, retain the state  
        // If both S and R are high, do nothing (undefined state)  
    end  
endmodule

module uart_controller (  
    input clk,  
    input reset,  
    input enable_tx,  
    input enable_rx,  
    input [7:0] tx_data,  
    output reg tx_busy,  
    output reg rx_ready,  
    output reg [7:0] rx_data  
);  
    reg [3:0] bit_count;  
    reg state; // 0: idle, 1: sending, 2: receiving  
    parameter IDLE = 0, SENDING = 1, RECEIVING = 2;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            bit_count <= 0;  
            state <= IDLE;  
            tx_busy <= 0;  
            rx_ready <= 0;  
            rx_data <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (enable_tx) begin  
                        state <= SENDING;  
                        tx_busy <= 1;  
                        bit_count <= 0;  
                    end else if (enable_rx) begin  
                        state <= RECEIVING;  
                        bit_count <= 0;  
                    end  
                end  
                SENDING: begin  
                    if (bit_count < 8) begin  
                        bit_count <= bit_count + 1;  
                    end else begin  
                        state <= IDLE;  
                        tx_busy <= 0;  
                    end  
                end  
                RECEIVING: begin  
                    if (bit_count < 8) begin  
                        // Simulate receiving data (for test purposes, just incrementing data)
                        rx_data[bit_count] <= 1'b1;  // Just a dummy implementation
                        bit_count <= bit_count + 1;  
                    end else begin  
                        state <= IDLE;  
                        rx_ready <= 1;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

module binary_counter (
    input clk,
    input reset,
    output reg [1:0] count
);
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 2'b00;
        end else begin
            count <= count + 1;
        end
    end
endmodule

module DES_round(
    input [63:0] block_in,
    input [55:0] key,
    output reg [63:0] block_out
);
    // Internal wires
    wire [31:0] left, right, new_right;
    wire [47:0] subkey;

    // Split the input block into left and right halves
    assign left = block_in[63:32];
    assign right = block_in[31:0];

    // Generate subkey (simple example, just a truncation for illustration)
    assign subkey = {key[55:0], 16'b0}; // Simple key mix (not actual DES logic)

    // DES round function: For simplicity, we will just XOR the right half with the subkey
    assign new_right = right ^ subkey;

    // Combine halves again (simplified without permutation)
    always @(*) begin
        block_out = {right, new_right}; // new_right is computed from the round function
    end
endmodule

module divide_by_4 (
    input clk,
    input rst,
    output reg out
);

reg [1:0] count;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        count <= 2'b00;
        out <= 1'b0;
    end else begin
        count <= count + 1;
        out <= (count == 2'b11) ? ~out : out;
    end
end

endmodule

module rca_4bit (  
    input [3:0] A,  
    input [3:0] B,  
    output [4:0] SUM  
);  
    wire [3:0] carry;  

    assign SUM[0] = A[0] ^ B[0];  
    assign carry[0] = A[0] & B[0];  

    assign SUM[1] = A[1] ^ B[1] ^ carry[0];  
    assign carry[1] = (A[1] & B[1]) | (carry[0] & (A[1] ^ B[1]));  

    assign SUM[2] = A[2] ^ B[2] ^ carry[1];  
    assign carry[2] = (A[2] & B[2]) | (carry[1] & (A[2] ^ B[2]));  

    assign SUM[3] = A[3] ^ B[3] ^ carry[2];  
    assign SUM[4] = (A[3] & B[3]) | (carry[2] & (A[3] ^ B[3]));  
endmodule

module two_bit_comparator(
    input [1:0] A,
    input [1:0] B,
    output reg A_eq,
    output reg A_gt,
    output reg A_lt
);

always @(*) begin
    A_eq = (A == B);
    A_gt = (A > B);
    A_lt = (A < B);
end

endmodule

module xnor3(input A, input B, input C, output Y);
    assign Y = ~(A ^ B) ^ C;
endmodule

module dma_controller (
    input wire clk,
    input wire rst,
    input wire start,
    input wire [7:0] src_addr,
    input wire [7:0] dest_addr,
    input wire [7:0] data_in,
    input wire rw, // 1 for write, 0 for read
    output reg transfer_complete,
    output reg [7:0] data_out
);
    reg [7:0] memory [0:255]; // 256 bytes of memory
    reg [7:0] current_src;
    reg [7:0] current_dest;
    reg state; // 0: idle, 1: transferring

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            transfer_complete <= 0;
            state <= 0;
        end else if (start && !state) begin
            current_src <= src_addr;
            current_dest <= dest_addr;
            state <= 1; // Start transferring
            transfer_complete <= 0;
        end else if (state) begin
            if (rw) begin // Write operation
                memory[current_dest] <= data_in;
            end else begin // Read operation
                data_out <= memory[current_src];
            end
            state <= 0; // Transfer complete
            transfer_complete <= 1;
        end
    end
endmodule

