module uart_transmitter (
    input clk,
    input reset,
    input [7:0] data_in,
    input send,
    output reg tx,
    output reg busy
);
    parameter BAUD_RATE_DIV = 104; // Assuming a 9600 baud rate with a 10MHz clock
    parameter IDLE = 0, START = 1, DATA = 2, STOP = 3;

    reg [3:0] state = IDLE;
    reg [3:0] bit_index = 0;
    reg [9:0] shift_reg; // 1 start bit + 8 data bits + 1 stop bit
    reg [6:0] baud_counter = 0;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            tx <= 1; // idle state for UART is high
            busy <= 0;
            bit_index <= 0;
            baud_counter <= 0;
        end else begin
            case (state)
                IDLE: begin
                    tx <= 1; // idle state
                    busy <= 0;
                    if (send) begin
                        shift_reg <= {1'b1, data_in, 1'b0}; // stop bits + data + start bit
                        state <= START;
                        busy <= 1;
                        bit_index <= 0;
                    end
                end
                START: begin
                    if (baud_counter == BAUD_RATE_DIV) begin
                        tx <= shift_reg[bit_index]; // output the current bit
                        bit_index <= bit_index + 1;
                        baud_counter <= 0;
                        if (bit_index == 9) // after sending all bits
                            state <= STOP;
                    end else begin
                        baud_counter <= baud_counter + 1;
                    end
                end
                STOP: begin
                    if (baud_counter == BAUD_RATE_DIV) begin
                        tx <= 1; // stop bit
                        state <= IDLE;
                        busy <= 0;
                        baud_counter <= 0;
                    end else begin
                        baud_counter <= baud_counter + 1;
                    end
                end
            endcase
        end
    end
endmodule

