module butterworth_filter (
    input wire clk,
    input wire reset,
    input wire [15:0] in_signal,
    output reg [15:0] out_signal
);

    // Filter coefficients (example values, should be calculated based on desired response)
    parameter [15:0] b0 = 16'h1A6C; // Coefficient for input
    parameter [15:0] b1 = 16'h1A6C; // Coefficient for delayed input
    parameter [15:0] a1 = 16'hE67A; // Coefficient for output

    reg [15:0] x_reg [1:0]; // Input registers
    reg [15:0] y_reg [1:0]; // Output registers

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            out_signal <= 16'b0;
            x_reg[0] <= 16'b0;
            x_reg[1] <= 16'b0;
            y_reg[0] <= 16'b0;
            y_reg[1] <= 16'b0;
        end else begin
            // Shift registers
            x_reg[1] <= x_reg[0];
            x_reg[0] <= in_signal;
            y_reg[1] <= y_reg[0];

            // Calculate output using the filter formula
            out_signal <= (b0 * x_reg[0] + b1 * x_reg[1] - a1 * y_reg[1]) >> 15; // Right shift for scaling
            y_reg[0] <= out_signal;
        end
    end
endmodule

