module clock_divider(  
    input clk_in,  
    input reset,  
    output reg clk_out  
);  
    reg [2:0] counter; // 3-bit counter for division by 8  

    always @(posedge clk_in or posedge reset) begin  
        if (reset) begin  
            counter <= 3'b000;  
            clk_out <= 0;  
        end else begin  
            if (counter == 3'b111) begin  
                clk_out <= ~clk_out;  
                counter <= 3'b000;  
            end else begin  
                counter <= counter + 1;  
            end  
        end  
    end  
endmodule

