module ofdm_modulator (
    input clk,
    input rst,
    input [7:0] serial_in,
    output reg [31:0] ofdm_symbol
);
    reg [7:0] subcarrier [0:3];
    reg [1:0] count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 0;
            ofdm_symbol <= 0;
        end else begin
            if (count < 4) begin
                subcarrier[count] <= serial_in;
                count <= count + 1;
            end else begin
                // IFFT operation simulated by concatenation for simplification
                ofdm_symbol <= {subcarrier[0], subcarrier[1], subcarrier[2], subcarrier[3]};
                count <= 0; // Reset count after processing
            end
        end
    end
endmodule

