module dma_controller (
    input wire clk,
    input wire reset,
    input wire [2:0] channel,
    input wire start,
    output reg busy,
    output reg done
);

    reg [2:0] current_channel;
    reg [2:0] state; // 0: IDLE, 1: BUSY

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            busy <= 0;
            done <= 0;
            state <= 0;
        end else begin
            case(state)
                0: begin // IDLE state
                    busy <= 0;
                    done <= 0;
                    if (start) begin
                        current_channel <= channel;
                        state <= 1; // Move to BUSY state
                    end
                end

                1: begin // BUSY state
                    busy <= 1;
                    // Simulate data transfer
                    // ... (data transfer logic here)
                    done <= 1; // Transfer completed
                    state <= 0; // Return to IDLE state
                end

                default: state <= 0; // Safety fallback
            endcase
        end
    end
endmodule

module bluetooth_fsm (  
    input clk,  
    input reset,  
    input start,  
    input disconnect,  
    output reg [1:0] state  
);  
    // State encoding  
    parameter IDLE = 2'b00,  
              CONNECTED = 2'b01,  
              DISCONNECTED = 2'b10;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (start)  
                        state <= CONNECTED;  
                end  
                CONNECTED: begin  
                    if (disconnect)  
                        state <= DISCONNECTED;  
                end  
                DISCONNECTED: begin  
                    if (reset)  
                        state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

