module fir_filter (  
    input [15:0] x_in,  
    output reg [15:0] y_out,  
    input clk  
);  
    reg [15:0] coeff [0:15];  
    reg [15:0] delay_line [0:15];  
    integer i;  
    initial begin  
        // Example coefficients for the FIR filter  
        coeff[0] = 16'h0001;  
        coeff[1] = 16'h0002;  
        coeff[2] = 16'h0003;  
        coeff[3] = 16'h0004;  
        coeff[4] = 16'h0005;  
        coeff[5] = 16'h0006;  
        coeff[6] = 16'h0007;  
        coeff[7] = 16'h0008;  
        coeff[8] = 16'h0009;  
        coeff[9] = 16'h000A;  
        coeff[10] = 16'h000B;  
        coeff[11] = 16'h000C;  
        coeff[12] = 16'h000D;  
        coeff[13] = 16'h000E;  
        coeff[14] = 16'h000F;  
        coeff[15] = 16'h0010;  
    end  
    always @(posedge clk) begin  
        // Shift the delay line  
        for (i = 15; i > 0; i = i - 1) begin  
            delay_line[i] <= delay_line[i - 1];  
        end  
        delay_line[0] <= x_in;  

        // Compute the output  
        y_out = 16'b0;  
        for (i = 0; i < 16; i = i + 1) begin  
            y_out = y_out + (delay_line[i] * coeff[i]);  
        end  
    end  
endmodule

