module lfsr_16bit (  
    input clk,  
    input rst,  
    input [15:0] seed,  
    output reg [15:0] lfsr_out  
);  
    wire feedback;  

    assign feedback = lfsr_out[15] ^ lfsr_out[13] ^ lfsr_out[12] ^ lfsr_out[10];  

    always @(posedge clk or posedge rst) begin  
        if (rst)  
            lfsr_out <= seed;  
        else  
            lfsr_out <= {lfsr_out[14:0], feedback};  
    end  
endmodule

