module pipeline_processor (  
    input clk,  
    input rst,  
    input [7:0] A, // Operand A  
    input [7:0] B, // Operand B  
    output reg [7:0] result // Output result  
);  
    reg [7:0] IF_A, IF_B;  
    reg [7:0] ID_A, ID_B;  
    reg [7:0] EX_A, EX_B;  
    reg [7:0] MEM_result;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            IF_A <= 0;  
            IF_B <= 0;  
            ID_A <= 0;  
            ID_B <= 0;  
            EX_A <= 0;  
            EX_B <= 0;  
            MEM_result <= 0;  
            result <= 0;  
        end else begin  
            // Stage 1: Instruction Fetch  
            IF_A <= A;  
            IF_B <= B;  

            // Stage 2: Instruction Decode  
            ID_A <= IF_A;  
            ID_B <= IF_B;  

            // Stage 3: Execute  
            EX_A <= ID_A;  
            EX_B <= ID_B;  

            // Stage 4: Memory Access (Not used in this simple addition)  
            MEM_result <= EX_A + EX_B;  

            // Stage 5: Write Back  
            result <= MEM_result;  
        end  
    end  
endmodule

