module pll (
    input wire clk_in,
    input wire reset,
    output reg clk_out
);
    reg [1:0] clk_div;
    reg vco;

    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            clk_div <= 2'b00;
            vco <= 1'b0;
            clk_out <= 1'b0;
        end else begin
            clk_div <= clk_div + 1;
            if (clk_div == 2'b01) begin
                vco <= ~vco; // Toggle VCO
            end
            clk_out <= vco; // Output the VCO signal
        end
    end
endmodule

