module watchdog_timer(  
    input clk,  
    input reset,  
    input trigger,  
    output reg timeout  
);  
    reg [3:0] count;  
    parameter THRESHOLD = 4'd10;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            count <= 4'd0;  
            timeout <= 0;  
        end else if (trigger) begin  
            count <= 4'd0;  
            timeout <= 0;  
        end else begin  
            if (count < THRESHOLD) begin  
                count <= count + 1;  
                timeout <= 0;  
            end else begin  
                timeout <= 1;  
            end  
        end  
    end  
endmodule

